-- Q7: total completed order value generated by their whole team fro every employee
;with EmployeeRevenue as
( 
select e.employee_id,
coalesce(sum(o.order_total),0) as team_total_revenue
from dbo.dim_employee as e left join dbo.fact_orders as o
on e.employee_id=o.sales_rep_id
group by e.employee_id

),
OrgTeam as(

select employee_id as team_leader_id,
employee_id as team_member_id
from dbo.dim_employee 

union all

select cte.team_leader_id,
e.employee_id as team_member_id
from dbo.dim_employee as e join OrgTeam as cte
on e.manager_id=cte.team_member_id
)
select e.employee_id,
e.employee_name,
e.role,
sum(er.team_total_revenue) as team_revenue
from dbo.dim_employee as e 
join OrgTeam as ot on e.employee_id=ot.team_leader_id
join EmployeeRevenue as er on ot.team_member_id=er.employee_id
group by e.employee_id,e.employee_name,e.role
option (maxrecursion 100)
Go
